from collections import defaultdict

a_note = 'Payment made on Venmo, receipt attached.'
our_email='matthew.blac@gmail.com'

# Assume venmo_transactions and all_groups, yesterday_date exist from earlier
print('venmo_transactions', [(t['transaction_id'], t['receiver']['email'], t['amount']) for t in venmo_transactions])
print('groups', [(g['group_id'], g['name']) for g in all_groups])

# Compute, for each venmo receiver/transaction, how much we owe in each splitwise group created yesterday,
# where our_email is among debtors in shares and the expense payer is the venmo receiver.

def compute_group_sums_for_receiver(receiver_email):
    sum_by_group = defaultdict(float)  # group_id or None

    # Grouped expenses
    for group in all_groups:
        gid = group['group_id']
        page_index = 0
        page_limit = 20
        while True:
            page = apis.splitwise.show_group_expenses(
                group_id=gid,
                access_token=splitwise_token,
                participant_email=receiver_email,
                min_created_at=yesterday_date,
                max_created_at=yesterday_date,
                page_index=page_index,
                page_limit=page_limit
            )
            if not page:
                break
            for exp in page:
                if exp.get('payer', {}).get('email') != receiver_email:
                    continue
                for share in exp.get('shares', []):
                    if share.get('debtor', {}).get('email') == our_email:
                        amt = float(share.get('debt_amount', 0.0))
                        if abs(amt) > 1e-9:
                            sum_by_group[gid] += amt
            page_index += 1

    # Non-group expenses
    page_index = 0
    page_limit = 20
    while True:
        page = apis.splitwise.show_no_group_expenses(
            access_token=splitwise_token,
            participant_email=receiver_email,
            min_created_at=yesterday_date,
            max_created_at=yesterday_date,
            page_index=page_index,
            page_limit=page_limit
        )
        if not page:
            break
        for exp in page:
            if exp.get('payer', {}).get('email') != receiver_email:
                continue
            for share in exp.get('shares', []):
                if share.get('debtor', {}).get('email') == our_email:
                    amt = float(share.get('debt_amount', 0.0))
                    if abs(amt) > 1e-9:
                        sum_by_group[None] += amt
        page_index += 1

    return dict(sum_by_group)

# Build payment plans aligned with each Venmo transaction amount.
payment_plans = []
for tx in venmo_transactions:
    tx_id = tx['transaction_id']
    receiver_email = tx['receiver']['email']
    tx_amount = round(float(tx['amount']), 2)

    sums = compute_group_sums_for_receiver(receiver_email)
    # Round sums for comparison
    sums_round = {k: round(float(v), 2) for k,v in sums.items()}

    total = round(sum(sums_round.values()), 2)
    print('\nTX', tx_id, 'to', receiver_email, 'amount', tx_amount, 'splitwise sums', sums_round, 'total', total)

    if total == 0:
        continue
    if total != tx_amount:
        # Still attempt to record only if rounding matches
        # If mismatch, record according to exact sums that do not exceed tx_amount? (avoid guessing)
        print('WARNING mismatch for tx', tx_id, 'tx_amount', tx_amount, 'total', total)

    # If the sums total matches tx_amount, record across each group with non-zero sum.
    if total == tx_amount:
        for gid, amt in sums_round.items():
            if abs(amt) < 1e-9:
                continue
            plan = {
                'tx_id': tx_id,
                'receiver_email': receiver_email,
                'group_id': gid,
                'amount': amt
            }
            payment_plans.append(plan)

print('\npayment_plans', payment_plans)
print('num plans', len(payment_plans))

