from collections import defaultdict
our_email='matthew.blac@gmail.com'
venmo_receivers={t['receiver']['email']:(t['transaction_id'],float(t['amount'])) for t in venmo_transactions}
print('venmo_receivers',venmo_receivers)

# Find splitwise group for each receiver: expenses created yesterday where payer==receiver and debtor includes our_email
receiver_group_sums=defaultdict(lambda: defaultdict(float))
receiver_total=defaultdict(float)
receiver_details=defaultdict(list)

for receiver_email,(tx_id,tx_amt) in venmo_receivers.items():
    for group in all_groups:
        gid=group['group_id']
        page_index=0
        page_limit=20
        while True:
            page=apis.splitwise.show_group_expenses(
                group_id=gid,
                access_token=splitwise_token,
                participant_email=receiver_email,
                min_created_at=yesterday_date,
                max_created_at=yesterday_date,
                page_index=page_index,
                page_limit=page_limit
            )
            if not page:
                break
            for exp in page:
                if exp.get('payer',{}).get('email')!=receiver_email:
                    continue
                for share in exp.get('shares',[]):
                    if share.get('debtor',{}).get('email')==our_email:
                        amt=float(share.get('debt_amount',0.0))
                        if abs(amt)>1e-9:
                            receiver_group_sums[receiver_email][gid]+=amt
                            receiver_total[receiver_email]+=amt
                            receiver_details[receiver_email].append({
                                'group_id':gid,
                                'expense_id':exp['expense_id'],
                                'expense_description':exp.get('description'),
                                'amount':amt,
                                'expense_created_at':exp.get('created_at'),
                            })
            page_index+=1

    # No-group entries where payer==receiver
    page_index=0
    while True:
        page=apis.splitwise.show_no_group_expenses(
            access_token=splitwise_token,
            participant_email=receiver_email,
            min_created_at=yesterday_date,
            max_created_at=yesterday_date,
            page_index=page_index,
            page_limit=20
        )
        if not page:
            break
        for exp in page:
            if exp.get('payer',{}).get('email')!=receiver_email:
                continue
            for share in exp.get('shares',[]):
                if share.get('debtor',{}).get('email')==our_email:
                    amt=float(share.get('debt_amount',0.0))
                    if abs(amt)>1e-9:
                        receiver_group_sums[receiver_email][None]+=amt
                        receiver_total[receiver_email]+=amt
                        receiver_details[receiver_email].append({
                            'group_id':None,
                            'expense_id':exp['expense_id'],
                            'expense_description':exp.get('description'),
                            'amount':amt,
                            'expense_created_at':exp.get('created_at'),
                        })
        page_index+=1

# Print results
for receiver_email,(tx_id,tx_amt) in venmo_receivers.items():
    print('\nReceiver',receiver_email,'Venmo tx',tx_id,'tx_amt',tx_amt)
    print('Splitwise total owed (yesterday, payer==receiver, debtor==me):',receiver_total.get(receiver_email,0.0))
    print('By group:',{k:v for k,v in receiver_group_sums[receiver_email].items()})
    print('Details count',len(receiver_details[receiver_email]))
    for d in receiver_details[receiver_email]:
        print(' ',d)

